import React, { useState } from 'react';
import { Container, Row, Col, Card, Form, Button, Alert, Badge } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import DatePicker from 'react-datepicker';
import { toast } from 'react-toastify';
import { userAPI } from '../../services/api';
import "react-datepicker/dist/react-datepicker.css";

const BookingForm = () => {
  const [formData, setFormData] = useState({
    title: '',
    purpose: '',
    request_type: 'room',
    date: new Date(),
    start_time: '',
    end_time: '',
    capacity: '',
    pic_name: '',
    pic_contact: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleDateChange = (date) => {
    setFormData({
      ...formData,
      date: date
    });
  };

  const validateForm = () => {
    if (!formData.title.trim()) return 'Judul acara harus diisi';
    if (!formData.purpose.trim()) return 'Tujuan harus diisi';
    if (!formData.start_time) return 'Waktu mulai harus diisi';
    if (!formData.end_time) return 'Waktu selesai harus diisi';
    if (!formData.capacity || formData.capacity < 1) return 'Kapasitas harus valid';
    if (!formData.pic_name.trim()) return 'Nama PIC harus diisi';
    if (!formData.pic_contact.trim()) return 'Kontak PIC harus diisi';

    // Validate time
    if (formData.start_time >= formData.end_time) {
      return 'Waktu selesai harus lebih besar dari waktu mulai';
    }

    // Validate date (not in the past)
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (formData.date < today) {
      return 'Tanggal tidak boleh di masa lalu';
    }

    return null;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    setError('');

    try {
      const submitData = {
        ...formData,
        date: formData.date.toISOString().split('T')[0], // Format YYYY-MM-DD
        capacity: parseInt(formData.capacity),
        pic_contact: formData.pic_contact, // Save to proper pic_contact field
        whatsapp_number: formData.pic_contact // Also save to whatsapp for backward compatibility
      };

      console.log('🔄 Submitting booking data:', submitData);
      await userAPI.createBooking(submitData);
      toast.success('Booking berhasil diajukan!');
      navigate('/user/mybookings');
    } catch (error) {
      console.error('❌ Booking submission error:', error);
      console.error('Error response:', error.response?.data);
      
      const errorMessage = error.response?.data?.message || 'Gagal membuat booking';
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container fluid className="py-4">
      <Row className="justify-content-center">
        <Col lg={10} xl={8}>
          {/* Header */}
          <div className="text-center mb-5 fade-in-up">
            <div className="bg-gradient-primary rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{ width: '80px', height: '80px' }}>
              <i className="fas fa-calendar-plus text-white fs-2"></i>
            </div>
            <h1 className="text-gradient mb-2">Buat Booking Baru</h1>
            <p className="text-muted fs-5 mb-0">
              <i className="fas fa-info-circle me-2"></i>
              Isi form berikut untuk mengajukan booking ruangan atau zoom meeting
            </p>
          </div>

          <Card className="shadow-lg border-0 fade-in-up" style={{ animationDelay: '0.2s' }}>
            <Card.Header className="bg-gradient text-white text-center py-4">
              <h4 className="mb-0 fw-bold">
                <i className="fas fa-building me-2"></i>
                Form Booking Meeting
              </h4>
            </Card.Header>
            <Card.Body className="p-4">
              {error && (
                <Alert variant="danger" className="border-0 shadow-soft fade-in-up">
                  <Alert.Heading className="h6 mb-2">
                    <i className="fas fa-exclamation-triangle me-2"></i>
                    Error
                  </Alert.Heading>
                  {error}
                </Alert>
              )}

              <Form onSubmit={handleSubmit}>
                {/* Basic Information */}
                <div className="mb-5">
                  <h5 className="text-primary mb-4 pb-2 border-bottom">
                    <i className="fas fa-info-circle me-2"></i>
                    Informasi Dasar
                  </h5>
                  
                  <Row>
                    <Col md={6}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-heading me-2 text-primary"></i>
                          Judul Acara <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Control
                          type="text"
                          name="title"
                          value={formData.title}
                          onChange={handleChange}
                          placeholder="Contoh: Meeting Project Alpha"
                          className="form-control-lg"
                          required
                        />
                      </Form.Group>
                    </Col>
                    <Col md={6}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-tag me-2 text-success"></i>
                          Jenis Booking <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Select
                          name="request_type"
                          value={formData.request_type}
                          onChange={handleChange}
                          className="form-control-lg"
                          required
                        >
                          <option value="room">
                            🏢 Ruangan Saja
                          </option>
                          <option value="zoom">
                            💻 Zoom Saja
                          </option>
                          <option value="both">
                            🏢💻 Ruangan + Zoom
                          </option>
                        </Form.Select>
                        <Form.Text className="text-muted">
                          <i className="fas fa-lightbulb me-1"></i>
                          Pilih sesuai kebutuhan meeting Anda
                        </Form.Text>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Form.Group className="mb-4">
                    <Form.Label className="fw-bold">
                      <i className="fas fa-bullseye me-2 text-warning"></i>
                      Tujuan/Keperluan <span className="text-danger">*</span>
                    </Form.Label>
                    <Form.Control
                      as="textarea"
                      rows={4}
                      name="purpose"
                      value={formData.purpose}
                      onChange={handleChange}
                      placeholder="Jelaskan tujuan penggunaan ruangan atau zoom meeting..."
                      className="form-control-lg"
                      required
                    />
                    <Form.Text className="text-muted">
                      <i className="fas fa-info-circle me-1"></i>
                      Deskripsikan secara singkat keperluan meeting Anda
                    </Form.Text>
                  </Form.Group>
                </div>

                {/* Date & Time Information */}
                <div className="mb-5">
                  <h5 className="text-primary mb-4 pb-2 border-bottom">
                    <i className="fas fa-clock me-2"></i>
                    Jadwal Meeting
                  </h5>
                  
                  <Row>
                    <Col md={4}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-calendar-day me-2 text-info"></i>
                          Tanggal <span className="text-danger">*</span>
                        </Form.Label>
                        <div className="position-relative">
                          <DatePicker
                            selected={formData.date}
                            onChange={handleDateChange}
                            minDate={new Date()}
                            dateFormat="dd/MM/yyyy"
                            className="form-control form-control-lg"
                            required
                            placeholderText="Pilih tanggal meeting"
                          />
                          <i className="fas fa-calendar-alt position-absolute top-50 end-0 translate-middle-y me-3 text-muted"></i>
                        </div>
                      </Form.Group>
                    </Col>
                    <Col md={3}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-play me-2 text-success"></i>
                          Waktu Mulai <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Control
                          type="time"
                          name="start_time"
                          value={formData.start_time}
                          onChange={handleChange}
                          className="form-control-lg"
                          required
                        />
                      </Form.Group>
                    </Col>
                    <Col md={3}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-stop me-2 text-danger"></i>
                          Waktu Selesai <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Control
                          type="time"
                          name="end_time"
                          value={formData.end_time}
                          onChange={handleChange}
                          className="form-control-lg"
                          required
                        />
                      </Form.Group>
                    </Col>
                    <Col md={2}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-users me-2 text-warning"></i>
                          Kapasitas <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Control
                          type="number"
                          name="capacity"
                          value={formData.capacity}
                          onChange={handleChange}
                          min="1"
                          max="100"
                          placeholder="10"
                          className="form-control-lg"
                          required
                        />
                        <Form.Text className="text-muted">
                          Jumlah peserta meeting
                        </Form.Text>
                      </Form.Group>
                    </Col>
                  </Row>
                </div>

                {/* Contact Information */}
                <div className="mb-5">
                  <h5 className="text-primary mb-4 pb-2 border-bottom">
                    <i className="fas fa-user-tie me-2"></i>
                    Informasi PIC (Person in Charge)
                  </h5>
                  
                  <Row>
                    <Col md={6}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-user me-2 text-primary"></i>
                          Nama PIC <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Control
                          type="text"
                          name="pic_name"
                          value={formData.pic_name}
                          onChange={handleChange}
                          placeholder="Nama Person in Charge"
                          className="form-control-lg"
                          required
                        />
                      </Form.Group>
                    </Col>
                    <Col md={6}>
                      <Form.Group className="mb-4">
                        <Form.Label className="fw-bold">
                          <i className="fas fa-phone me-2 text-success"></i>
                          Kontak PIC <span className="text-danger">*</span>
                        </Form.Label>
                        <Form.Control
                          type="text"
                          name="pic_contact"
                          value={formData.pic_contact}
                          onChange={handleChange}
                          placeholder="Nomor HP atau Email"
                          className="form-control-lg"
                          required
                        />
                        <Form.Text className="text-muted">
                          <i className="fas fa-info-circle me-1"></i>
                          Kontak yang bisa dihubungi saat meeting
                        </Form.Text>
                      </Form.Group>
                    </Col>
                  </Row>
                </div>

                {/* Action Buttons */}
                <div className="text-center pt-4 border-top">
                  <Button 
                    variant="outline-secondary" 
                    size="lg"
                    className="me-3 px-4" 
                    onClick={() => navigate('/user/dashboard')}
                  >
                    <i className="fas fa-arrow-left me-2"></i>
                    Batal
                  </Button>
                  <Button 
                    variant="primary" 
                    type="submit"
                    size="lg"
                    className="px-5 shadow-soft"
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2"></span>
                        Menyimpan...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-paper-plane me-2"></i>
                        Ajukan Booking
                      </>
                    )}
                  </Button>
                </div>
              </Form>
            </Card.Body>
          </Card>
          
          {/* Help Card */}
          <Card className="mt-4 shadow-soft border-0 fade-in-up" style={{ animationDelay: '0.4s' }}>
            <Card.Body className="text-center py-4">
              <h6 className="text-muted mb-3">
                <i className="fas fa-question-circle me-2"></i>
                Butuh Bantuan?
              </h6>
              <p className="text-muted mb-0">
                Hubungi admin IT jika Anda mengalami kesulitan dalam membuat booking atau memiliki pertanyaan khusus.
              </p>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default BookingForm;
